contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a target contract address, arrays of tos and vs. The rule: when transfer returns (doesn't revert)
    // it must return true. If it reverts, our 'reverted' flag is true. We assert that return==true iff not reverted.
    function run(address contract_address, address[] memory tos, uint[] memory vs) public payable {
        require(contract_address != address(0x0));
        require(contract_address != address(c));
        // preconditions matching C's modifier and some basic lengths to allow both success and revert paths
        // but do not require tos.length>0 or vs.length>0; we want to observe both behaviors

        bool reverted;
        bool ret;
        try c.transfer(contract_address, tos, vs) {
            reverted = false;
            // call returned successfully; we can query nothing else, but capture true/false by calling again is not allowed
            // The function returns (bool) so try-catch without assignment means success; but we cannot read the returned value here.
            // To capture the returned value we need to assign via = c.transfer(...); but that would revert on revert, so use try with return value.
        } catch {
            reverted = true;
        }

        // To capture the return value when it does not revert, call again inside a guarded require to avoid changing state: transfer has side-effects, cannot call twice safely.
        // Instead, use try with returned value properly above. Re-do using try with return value.
        // Because we already made a call, but the template restricts that all state-changing calls must be top-level statements — try is top-level. We'll redo via fresh variables.

        // Re-run but capture return value properly. Note: performing the call twice may change external contract state; however, the checker runs on fresh c and this single run invocation; making a second call is allowed.
        bool reverted2;
        bool returnedValue;
        try c.transfer(contract_address, tos, vs) returns (bool r) {
            reverted2 = false;
            returnedValue = r;
        } catch {
            reverted2 = true;
            returnedValue = false;
        }

        // Our invariant: transfer must either revert, or return true. It should not return false when it completes.
        // So assert that if it did not revert then returnedValue == true. Also ensure consistency that the two attempts produce same revert-ness when possible.
        // We assert the general property using the second attempt's observed values.
        assert(!(reverted2 == false && returnedValue == false));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We require contract_address to be non-zero and not c (matching C's modifier),
    // and require tos and vs to be non-empty and same length so the call can potentially succeed.
    // The property: whenever c.transfer(...) call does not revert, its returned bool must be true.
    function run(address contract_address, address[] memory tos, uint[] memory vs) public payable {
        require(contract_address != address(0x0));
        require(contract_address != address(c));
        require(tos.length > 0);
        require(vs.length > 0);
        require(tos.length == vs.length);

        bool didRevert;
        bool returnedValue;
        try c.transfer(contract_address, tos, vs) returns (bool r) {
            didRevert = false;
            returnedValue = r;
        } catch {
            didRevert = true;
            returnedValue = false;
        }

        // Assert the general rule: if the call did not revert, it must have returned true.
        assert(didRevert || returnedValue == true);
    }

    receive() external payable { }
}

contract InvMutTest {
